using Microsoft.EntityFrameworkCore;
using OrcaFacil.Application.DTOs;
using OrcaFacil.Domain.Enums;
namespace OrcaFacil.Persistence.Queries;

public class SuperAdminDashboardQueries { private readonly OrcaFacilDbContext _db; public SuperAdminDashboardQueries(OrcaFacilDbContext db) => _db = db; public async Task<SuperAdminDashboardDto> GetAsync(CancellationToken ct = default) { var month = new DateTime(DateTime.UtcNow.Year, DateTime.UtcNow.Month, 1, 0, 0, 0, DateTimeKind.Utc); var dto = new SuperAdminDashboardDto { TotalUsers = await _db.Users.CountAsync(ct), ActiveUsers = await _db.Users.CountAsync(x => x.IsActive && !x.IsBlocked, ct), BlockedUsers = await _db.Users.CountAsync(x => x.IsBlocked, ct), FreeUsers = await _db.Users.CountAsync(x => x.Plan == PlanType.Free, ct), ProUsers = await _db.Users.CountAsync(x => x.Plan == PlanType.Pro, ct), TotalClients = await _db.Clients.CountAsync(ct), TotalDocuments = await _db.Documents.CountAsync(ct), TotalBudgets = await _db.Documents.CountAsync(x => x.Type == DocumentType.Budget, ct), TotalReceipts = await _db.Documents.CountAsync(x => x.Type == DocumentType.Receipt, ct), TotalPayments = await _db.Payments.CountAsync(ct), ApprovedPaymentsAmountMonth = await _db.Payments.Where(x => x.Status == PaymentStatus.Approved && x.CreatedAt >= month).SumAsync(x => (decimal?)x.Amount, ct) ?? 0, PendingPaymentsAmount = await _db.Payments.Where(x => x.Status == PaymentStatus.Pending).SumAsync(x => (decimal?)x.Amount, ct) ?? 0, OverduePaymentsAmount = await _db.Payments.Where(x => x.Status == PaymentStatus.Expired).SumAsync(x => (decimal?)x.Amount, ct) ?? 0 }; dto.MrrEstimate = dto.ProUsers * 19.90m; dto.PastDueUsers = await _db.Subscriptions.CountAsync(x => x.Status == SubscriptionStatus.PastDue, ct); dto.SuspendedUsers = await _db.Subscriptions.CountAsync(x => x.Status == SubscriptionStatus.Suspended, ct); dto.RecentUsers = await _db.Users.OrderByDescending(x => x.CreatedAt).Take(8).Select(x => new SuperAdminUserRowDto(x.Name, x.Email, x.Plan.ToString(), 0, 0, x.LastLoginAt, x.IsBlocked ? "Bloqueado" : "Ativo")).ToListAsync(ct); dto.RecentPayments = await _db.Payments.OrderByDescending(x => x.CreatedAt).Take(8).Select(x => new SuperAdminPaymentRowDto(x.PayerEmail ?? x.UserId.ToString(), x.Plan.ToString(), x.Amount, x.PaymentMethod ?? "Manual", x.Status.ToString(), x.DueDate, x.PaidAt, x.ExternalPaymentId)).ToListAsync(ct); dto.RecentErrors = await _db.SystemErrors.OrderByDescending(x => x.CreatedAt).Take(5).Select(x => x.Message).ToListAsync(ct); return dto; } }
